import {execute as base,scenario,simulatePath,compare,parseMoney,modelLimitations,amount,VERSION,RULES,SOURCE} from './engine.mjs';
class ErrorInput extends Error {constructor(message,field,status='invalid_input'){super(message);this.field=field;this.status=status;}}
const fail=(m,f,s)=>{throw new ErrorInput(m,f,s);};
const meta={calculationVersion:VERSION,rulesVersion:RULES,checkedAt:'2026-11-08',currency:'PLN',sources:[SOURCE]};
const baseFields=['initialPln','monthlyPln','years','annualReturnPercent','annualFixedFeePln','annualFeePercent'];
const taxFields=['group','futureTaxPercent','thresholdIndexationPercent'];
const capitalLimits=['Model planistyczny bez podatków, walut, dywidend i gwarancji przyszłego wyniku.','Wpłaty na początku miesiąca, wzrost na koniec miesiąca, wypłaty na koniec miesiąca po wzroście. Stały roczny zwrot jest jawnym założeniem.','Koszty stałe i procentowe pobierane na końcu roku. Brak prowizji, minimów taryfowych i kosztów transakcji.','Model miesięczny nie wyznacza ustawowych średnich OKI. Wynik może różnić się od modelu dziennego.'];
const money=(v,f)=>Number(parseMoney(v,f))/100;
function num(v,f,min,max,int=false){if(v===undefined||v===null||v==='')fail('Uzupełnij pole.',f,'needs_data');if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||(int&&!Number.isInteger(v)))fail(`Podaj wartość ${min}–${max}.`,f);return v;}
function exact(v,keys){if(!v||typeof v!=='object'||Array.isArray(v))fail('Podaj obiekt danych.','input');for(const k of Object.keys(v))if(!keys.includes(k))fail('Nieobsługiwane pole.',k);}
const select=(input,fields)=>Object.fromEntries(fields.map(k=>[k,input[k]]));
function plan(input,extra=[],tax=false){exact(input,[...baseFields,...(tax?taxFields:[]),...extra]);return scenario(select(input,baseFields));}
function checkTax(input){const r=base('compare_oki_scenarios',select(input,[...baseFields,...taxFields]));if(r.status!=='ok')fail(r.message,r.field,r.status);return r;}
const sum=x=>x.reduce((a,b)=>a+b,0);
const metric=(label,value,unit='PLN')=>({label,value:unit==='PLN'?amount(value):value,unit});
function result(input,metrics,rows=[],limitations=capitalLimits,extra={}){return {...meta,status:'ok',input,calculationMode:'planning_scenario',metrics,rows,limitations,...extra};}
// A common monthly engine for goals, flexibility and withdrawals; no implicit tax assumptions.
function path(p,{deposit,withdraw,expense,annualRates}={}){
 let balance=p.initial,paid=p.initial,out=0,fees=0,exhaustedMonth=null;const rows=[];
 for(let month=1;month<=p.years*12;month++){
  const add=deposit?deposit(month):p.monthly;balance+=add;paid+=add;
  const rate=annualRates?annualRates[Math.floor((month-1)/12)]/100:p.rate;
  balance*=Math.pow(1+rate,1/12);
  const requested=(withdraw?.(month)??0)+(expense?.(month)??0);
  const taken=Math.min(balance,requested);out+=taken;balance-=taken;
  if(requested>taken+0.000001&&exhaustedMonth===null)exhaustedMonth=month;
  if(month%12===0){const fee=Math.min(balance,p.fixed+balance*p.fee);balance-=fee;fees+=fee;rows.push({year:2026+month/12,balancePln:amount(balance),contributionsPln:amount(paid),withdrawalsPln:amount(out),feesPln:amount(fees)});}
  if(!Number.isFinite(balance)||balance>1e13)fail('Wynik poza zakresem modelu.','scenario','unsupported_case');
 }
 return {balance,paid,out,fees,exhaustedMonth,rows};
}
function solveIncreasing(fn,target,lo,hi){if(fn(lo)>=target)return lo;if(fn(hi)<target)return null;for(let j=0;j<50;j++){const m=(lo+hi)/2;if(fn(m)>=target)hi=m;else lo=m;}return hi;}
const basicSummary=r=>[metric('Kapitał na końcu, bez podatków',r.balance),metric('Wpłacony kapitał',r.paid),metric('Pobrane opłaty',r.fees)];
function goal(input){const p=plan(input,['targetPln','mode']);const target=money(input.targetPln,'targetPln');
 if(input.mode==='contribution'){
  const monthly=solveIncreasing(v=>path({...p,monthly:v}).balance,target,0,10000000);
  if(monthly===null)return result(input,[],[],capitalLimits,{status:'no_solution',message:'Cel nieosiągalny przy wpłacie do 10 mln zł miesięcznie w zadanym okresie.'});
  const rounded=Math.ceil(monthly*100-1e-6)/100,r=path({...p,monthly:rounded});
  return result(input,[metric('Miesięczna wpłata do celu',rounded),metric('Cel',target),...basicSummary(r)],r.rows,capitalLimits,{solver:{tolerancePln:0.01,maxMonthlyPln:10000000}});
 }
 if(input.mode==='time'){
  if(p.initial>=target)return result(input,[metric('Lata do celu',0,'years'),metric('Kwota celu',target)],[],capitalLimits);
  for(let years=1;years<=p.years;years++){const r=path({...p,years});if(r.balance>=target)return result(input,[metric('Pełne lata do celu',years,'years'),...basicSummary(r)],r.rows,capitalLimits);}
  return result(input,[],[],capitalLimits,{status:'no_solution',message:'Cel nie został osiągnięty na końcu żadnego pełnego roku w zadanym zakresie.'});
 }fail('Wybierz contribution lub time.','mode');
}
function flexibility(input){const extras=['mode','pauseFromMonth','pauseMonths','annualContributionGrowthPercent','deposits','expensePln','expenseMonth'];const p=plan(input,extras);const baseline=path(p);let options={};
 if(input.mode==='pause'){const from=num(input.pauseFromMonth,'pauseFromMonth',1,p.years*12,true),count=num(input.pauseMonths,'pauseMonths',1,p.years*12,true);if(from+count-1>p.years*12)fail('Przerwa wykracza poza horyzont.','pauseMonths');options.deposit=m=>m>=from&&m<from+count?0:p.monthly;}
 else if(input.mode==='growth'){const growth=num(input.annualContributionGrowthPercent,'annualContributionGrowthPercent',0,100)/100;options.deposit=m=>p.monthly*Math.pow(1+growth,Math.floor((m-1)/12));}
 else if(input.mode==='schedule'){if(!Array.isArray(input.deposits)||input.deposits.length>480)fail('Podaj listę do 480 wpłat.','deposits');const deps=new Map();input.deposits.forEach((d,i)=>{exact(d,['month','amountPln']);const m=num(d.month,`deposits.${i}.month`,1,p.years*12,true);deps.set(m,(deps.get(m)??0)+money(d.amountPln,`deposits.${i}.amountPln`));});options.deposit=m=>deps.get(m)??0;}
 else if(input.mode==='expense'){const value=money(input.expensePln,'expensePln'),when=num(input.expenseMonth,'expenseMonth',1,p.years*12,true);options.expense=m=>m===when?value:0;}
 else fail('Nieobsługiwany tryb planu.','mode');
 const r=path(p,options);
 return result(input,[...basicSummary(r),metric('Kapitał wariantu bazowego',baseline.balance),metric('Zmiana kapitału względem bazy',r.balance-baseline.balance),metric('Wypłacono łącznie',r.out)],r.rows,[...capitalLimits,'Nieregularne wpłaty: lista zastępuje stałe wpłaty bazowe. Numer miesiąca 1 oznacza styczeń 2027 r.'],{exhaustedMonth:r.exhaustedMonth,...(r.exhaustedMonth?{status:'insufficient_funds',message:`Brak środków na pełną wypłatę w miesiącu ${r.exhaustedMonth}. Podano tylko wypłacone kwoty.`}:{})});
}
function withdrawals(input){const p=plan(input,['mode','monthlyWithdrawalPln']);let value;
 if(input.mode==='solve'){
  // Seek the largest amount that is fully paid throughout the requested horizon.
  let lo=0,hi=(p.initial+p.monthly*p.years*12)*Math.pow(1+Math.max(0,p.rate),p.years)+1;
  for(let i=0;i<55;i++){const m=(lo+hi)/2,r=path(p,{withdraw:()=>m});if(r.exhaustedMonth===null)lo=m;else hi=m;}value=Math.floor(lo*100)/100;
 }else if(input.mode==='fixed')value=money(input.monthlyWithdrawalPln,'monthlyWithdrawalPln');else fail('Wybierz solve lub fixed.','mode');
 const r=path(p,{withdraw:()=>value});return result(input,[metric('Miesięczna wypłata w modelu, przed podatkami',value),metric('Wypłacono łącznie',r.out),metric('Pozostały kapitał',r.balance),metric('Suma opłat',r.fees)],r.rows,[...capitalLimits,'Wyliczona wypłata nie jest gwarantowanym ani bezpiecznym dochodem. Brak podatku i kosztów sprzedaży instrumentów.'],{exhaustedMonth:r.exhaustedMonth,...(r.exhaustedMonth?{status:'insufficient_funds',message:`Kapitał nie pokrywa całej wypłaty od miesiąca ${r.exhaustedMonth}.`}:{})});
}
function fees(input){const p=plan(input,['alternativeFixedFeePln','alternativeFeePercent']);const a=path(p),b=path({...p,fixed:money(input.alternativeFixedFeePln,'alternativeFixedFeePln'),fee:num(input.alternativeFeePercent,'alternativeFeePercent',0,10)/100});return result(input,[metric('Kapitał według taryfy A',a.balance),metric('Kapitał według taryfy B',b.balance),metric('Opłaty A',a.fees),metric('Opłaty B',b.fees),metric('Różnica kapitału B minus A',b.balance-a.balance)],a.rows,[...capitalLimits,'To porównanie dwóch własnych uproszczonych taryf. Nie obejmuje wszystkich opłat konkretnej oferty.']);}
function rates(input){plan(input,['alternativeTaxPercent'],true);const a=checkTax(input),alt=num(input.alternativeTaxPercent,'alternativeTaxPercent',0.1,5),b=compare({...select(input,[...baseFields,...taxFields]),futureTaxPercent:alt});return result(input,[metric('OKI — stawka bazowa od 2028',Number(a.oki.balancePln)),metric('OKI — alternatywna stawka od 2028',Number(b.oki.balancePln)),metric('Różnica alternatywa minus baza',Number(b.oki.balancePln)-Number(a.oki.balancePln))],a.oki.rows,a.limitations);}
function sensitivity(input){plan(input,['lowerReturnPercent','higherReturnPercent','inflationPercent'],true);checkTax(input);const low=num(input.lowerReturnPercent,'lowerReturnPercent',-50,50),high=num(input.higherReturnPercent,'higherReturnPercent',-50,50),infl=num(input.inflationPercent,'inflationPercent',-5,30)/100;if(low>input.annualReturnPercent||high<input.annualReturnPercent)fail('Zachowaj kolejność: niższy ≤ bazowy ≤ wyższy zwrot.','lowerReturnPercent');
 const rows=[low,input.annualReturnPercent,high].map(rate=>{const r=compare({...select(input,[...baseFields,...taxFields]),annualReturnPercent:rate});return {variant:`Zwrot ${rate}%`,okiNetPln:r.oki.balancePln,ordinaryNetPln:r.ordinary.netBalancePln,realOkiNetPln:amount(Number(r.oki.balancePln)/Math.pow(1+infl,input.years)),differencePln:r.differencePln};});return result(input,[],rows,[...modelLimitations,'Trzy jawne warianty, bez prawdopodobieństw. Wartości realne w sile nabywczej początku 2027 r.; inflacja jest założeniem.']);}
function sequence(input){const p=plan(input,['annualReturnsPercent','monthlyWithdrawalPln']);if(!Array.isArray(input.annualReturnsPercent)||input.annualReturnsPercent.length!==p.years)fail('Podaj jedną stopę zwrotu dla każdego roku.','annualReturnsPercent');const returns=input.annualReturnsPercent.map((r,i)=>num(r,`annualReturnsPercent.${i}`,-50,50));const w=money(input.monthlyWithdrawalPln,'monthlyWithdrawalPln');const a=path(p,{annualRates:returns,withdraw:()=>w}),b=path(p,{annualRates:[...returns].reverse(),withdraw:()=>w});return result(input,[metric('Kapitał — kolejność podana',a.balance),metric('Kapitał — kolejność odwrócona',b.balance),metric('Wypłacono — podana',a.out),metric('Wypłacono — odwrócona',b.out)],a.rows,[...capitalLimits,'Odwrócenie tej samej listy zwrotów nie jest prognozą. Wyczerpanie kapitału oznacza wypłaty mniejsze od zadanych.'],{exhaustedMonthOriginal:a.exhaustedMonth,exhaustedMonthReversed:b.exhaustedMonth});}
function horizon(input){plan(input,[],true);checkTax(input);const rows=[];for(let years=1;years<=input.years;years++){const r=compare({...select(input,[...baseFields,...taxFields]),years});rows.push({year:2026+years,okiPln:r.oki.balancePln,ordinaryPln:r.ordinary.netBalancePln,differencePln:r.differencePln});}const crossings=[];for(let i=1;i<rows.length;i++)if(Math.sign(Number(rows[i].differencePln))!==Math.sign(Number(rows[i-1].differencePln)))crossings.push({fromYear:rows[i-1].year,toYear:rows[i].year});return result(input,[],rows,[...modelLimitations,'Sprawdzenie na końcu kolejnych pełnych lat, nie dokładny ciągły próg czasu. Możliwe zero, jeden lub wiele przejść.'],{crossings});}
function feeThreshold(input){const p=plan(input,[],true),r=checkTax(input),target=Number(r.ordinary.netBalancePln);const fn=extra=>Number(simulatePath({...p,fee:p.fee+extra},{group:input.group,futureRate:input.futureTaxPercent/100,indexation:input.thresholdIndexationPercent/100}).balancePln)-target;const max=0.10-p.fee;const initial=fn(0),last=fn(max);if(initial<0||last>0)return result(input,[],[],r.limitations,{status:'no_solution',message:initial<0?'OKI już ma niższy modelowy wynik przy zerowej dodatkowej opłacie.':'Wyniki nie zrównują się przy łącznej opłacie procentowej do 10%.'});let lo=0,hi=max;for(let i=0;i<40;i++){const mid=(lo+hi)/2;if(fn(mid)>=0)lo=mid;else hi=mid;}return result(input,[metric('Dodatkowa roczna opłata procentowa przy zrównaniu',Number((lo*100).toFixed(6)),'percent')],[],[...r.limitations,'Próg dotyczy dodatkowej opłaty procentowej tylko w OKI; pozostałe parametry bez zmian. Zakres łącznej opłaty do 10%.']);}
function split(input){const p=plan(input,['okiSharePercent'],true);const r=checkTax(input),share=num(input.okiSharePercent,'okiSharePercent',0,100)/100;
 const oki=simulatePath({...p,initial:p.initial*share,monthly:p.monthly*share,fixed:share===0?0:p.fixed},{group:input.group,futureRate:input.futureTaxPercent/100,indexation:input.thresholdIndexationPercent/100});const q={...p,initial:p.initial*(1-share),monthly:p.monthly*(1-share),fixed:share===1?0:p.fixed},ord=simulatePath(q);const pit=Math.max(0,Number(ord.balancePln)-q.initial-12*q.monthly*q.years)*.19;const total=Number(oki.balancePln)+Number(ord.balancePln)-pit;return result(input,[metric('Kapitał wariantu podzielonego',total),metric('Część OKI',Number(oki.balancePln)),metric('Część zwykłego rachunku po sprzedaży',Number(ord.balancePln)-pit),metric('Całość na OKI — wariant odniesienia',Number(r.oki.balancePln)),metric('Całość na zwykłym — wariant odniesienia',Number(r.ordinary.netBalancePln))],oki.rows,[...r.limitations,'Podany udział dotyczy kwoty początkowej i wszystkich nowych wpłat. Stała taryfa per aktywne konto, a nie raz dla całego portfela. Porównujemy wskazany podział, nie szukamy optymalnej alokacji.']);}
function family(input){plan(input,['secondInitialPln','secondMonthlyPln','secondGroup'],true);const a=checkTax(input),b=base('compare_oki_scenarios',{...select(input,[...baseFields,...taxFields]),initialPln:input.secondInitialPln,monthlyPln:input.secondMonthlyPln,group:input.secondGroup});if(b.status!=='ok')fail(b.message,b.field,b.status);return result(input,[metric('Właściciel A — kapitał OKI',Number(a.oki.balancePln)),metric('Właściciel B — kapitał OKI',Number(b.oki.balancePln)),metric('Suma planów — osobni właściciele',Number(a.oki.balancePln)+Number(b.oki.balancePln)),metric('Suma modelowych podatków OKI',Number(a.oki.taxPln)+Number(b.oki.taxPln))],[],[...a.limitations.slice(1),'Dwa niezależne rachunki podatkowe dorosłych właścicieli. Nie tworzymy wspólnego limitu, nie modelujemy darowizn ani zmiany własności. Wspólny horyzont, zwrot i taryfa są jawnym uproszczeniem.']);}
function exemptionChange(input){exact(input,['before','after']);const calc=v=>{exact(v,['S','I','N']);const r=base('calculate_oki_tax_from_averages',{taxYear:2027,accounts:[{savingsGroupAveragePln:v.S,investmentGroupAveragePln:v.I,nonExemptGroupAveragePln:v.N}]});if(r.status!=='ok')fail(r.message,r.field,r.status);return r;};const a=calc(input.before),b=calc(input.after);return result(input,[metric('Podstawa przed zmianą',Number(a.taxBasePln)),metric('Podstawa po zmianie',Number(b.taxBasePln)),metric('Kwota arytmetyczna przed',Number(a.taxBeforeFinalRoundingPln)),metric('Kwota arytmetyczna po',Number(b.taxBeforeFinalRoundingPln))],[],[...a.limitations,'Porównanie dwóch zestawów już ustalonych średnich. Nie wyznacza dostępnej kwoty wpłaty ani skutków zmiany klasyfikacji w trakcie roku.'],{before:a,after:b});}
function realization(input){const p=plan(input);let balance=p.initial,taxes=0;const rows=[];for(let y=0;y<p.years;y++){const q=simulatePath({...p,initial:balance,years:1,startYear:2027+y});const gain=Math.max(0,Number(q.balancePln)-balance-12*p.monthly);const tax=gain*.19;balance=Number(q.balancePln)-tax;taxes+=tax;rows.push({year:2027+y,balancePln:amount(balance),taxPln:amount(tax)});}const last=simulatePath(p);const finalTax=Math.max(0,Number(last.balancePln)-p.initial-12*p.monthly*p.years)*.19;return result(input,[metric('Sprzedaż co roku — kapitał netto',balance),metric('Sprzedaż na końcu — kapitał netto',Number(last.balancePln)-finalTax),metric('Suma podatków przy sprzedaży co roku',taxes),metric('Podatek przy sprzedaży na końcu',finalTax)],rows,[...modelLimitations,'Porównanie tylko zwykłego rachunku, uproszczony PIT 19% dodatniego zysku po kosztach. Brak kompensacji strat między latami, prowizji sprzedaży i odkupienia.']);}
const ops={solve_oki_goal:goal,simulate_flexible_plan:flexibility,simulate_oki_withdrawals:withdrawals,compare_fee_scenarios:fees,analyze_oki_sensitivity:sensitivity,compare_return_sequences:sequence,compare_future_tax_rates:rates,find_oki_horizon_crossings:horizon,find_oki_fee_threshold:feeThreshold,compare_oki_allocation:split,simulate_family_plans:family,compare_oki_exemptions:exemptionChange,compare_realization_frequency:realization};
export function extendedExecute(name,input){try{if(!ops[name])return null;return ops[name](input);}catch(e){return {...meta,status:e.status??'invalid_input',field:e.field??'input',message:e instanceof ErrorInput?e.message:e.message??'Nieprawidłowe dane.'};}}
export const plannerOperations=Object.keys(ops);
